theorem kernelBudgetError_apply_univ {d : X → ℝ} (hd : Measurable d) {x : X}
    (hd0 : 0 ≤ d x) : kernelBudgetError κ ν d x univ = kernelSingularPart κ ν x univ +
      ENNReal.ofReal (min (∫ y, ‖kernelRealDensity κ ν (x, y)‖ ∂ν) (d x))
